  for(var i=0;i<m;i++) for(var j=0;j<k;j++){ var a=i*n+j, b=(i+m)*n+j, t=q[a]; q[a]=q[b]; q[b]=t; }
  for(var i2=0;i2<m;i2++) for(var j2=0;j2<k-1;j2++){ var c=2*m-1-j2, a2=i2*n+c, b2=(i2+m)*n+c, t2=q[a2]; q[a2]=q[b2]; q[b2]=t2; }
  var a1=mid*n+0, b1=(m+mid)*n+0, t1=q[a1]; q[a1]=q[b1]; q[b1]=t1;
  var a2=mid*n+mid, b2=(m+mid)*n+mid, t2=q[a2]; q[a2]=q[b2]; q[b2]=t2;
